       ast41_limit_rate        = #{req.limitRate},
       ast41_stop_loss_rate    = #{req.stopLossRate},
       ast41_note              = #{req.note}
 WHERE ast41_invest_limit_id = #{req.investLimitId}
   AND ast41_company_id = #{companyId}

